import "@material/web/slider/slider.js";

import type { MdSlider } from "@material/web/slider/slider.js";
import { css, html, LitElement } from "lit";
import { customElement, property } from "lit/decorators.js";
import { isFunction } from "tone";

import { Bindable } from "../bind";

/**
 * A Param or Signal, or a callback which receives the slider value
 */
type SliderTarget = { value: number } | ((value: number) => void);

@customElement("tone-slider")
export class ToneSlider extends LitElement implements Bindable<SliderTarget> {
	@property({ type: Number })
	min = 0;

	@property({ type: Number })
	max = 100;

	@property({ type: Number, reflect: true })
	value = 50;

	/**
	 * The slider increment. 0 means continuous.
	 */
	@property({ type: Number })
	step = 0;

	@property({ type: String })
	label = "";

	@property({ type: String })
	units = "";

	static override styles = css`
		:host {
			display: block;
			width: 100%;
		}
		#label {
			display: block;
			width: 100%;
		}
		.value {
			margin-left: 10px;
			font-weight: bold;
			float: right;
		}
		.units {
			font-weight: normal;
		}
		md-slider {
			display: block;
			/* md-slider pads its track by half the state layer size,
			pull it out so the track lines up with the label */
			margin-inline: calc(var(--md-slider-state-layer-size, 40px) / -2);
			--md-slider-active-track-color: black;
			--md-slider-handle-color: black;
			--md-slider-focus-handle-color: black;
			--md-slider-hover-handle-color: black;
			--md-slider-pressed-handle-color: black;
			--md-slider-hover-state-layer-color: black;
			--md-slider-pressed-state-layer-color: black;
			--md-slider-inactive-track-color: rgba(0, 0, 0, 0.26);
			--md-slider-active-track-height: 2px;
			--md-slider-inactive-track-height: 2px;
			--md-slider-handle-width: 12px;
			--md-slider-handle-height: 12px;
		}
	`;

	/**
	 * Set the target's value when the slider moves. A Param or Signal
	 * target also sets the slider's starting value.
	 */
	bind(target: SliderTarget) {
		if (isFunction(target)) {
			this.addEventListener("input", () => target(this.value));
		} else {
			this.value = target.value;
			this.addEventListener("input", () => (target.value = this.value));
		}
	}

	/**
	 * The input event is composed, so it continues on to
	 * listeners on the host after the value is updated here.
	 */
	private _input(e: Event) {
		this.value = (e.target as MdSlider).value;
	}

	/**
	 * md-slider needs a numeric step, so approximate continuous
	 * movement with a fine subdivision of the range
	 */
	private _sliderStep(): number {
		return this.step || (this.max - this.min) / 1000;
	}

	private _beautifyValue(value: number): string {
		if (Number.isInteger(value)) {
			return value.toString();
		} else {
			return value.toFixed(2);
		}
	}

	protected override render() {
		return html`
			<div id="label">
				<label for="slider">${this.label}</label>
				<span class="value"
					>${this._beautifyValue(this.value)}
					<span class="units">${this.units}</span></span
				>
			</div>
			<md-slider
				id="slider"
				.min=${this.min}
				.max=${this.max}
				.step=${this._sliderStep()}
				.value=${this.value}
				@input=${this._input}
			></md-slider>
		`;
	}
}

declare global {
	interface HTMLElementTagNameMap {
		"tone-slider": ToneSlider;
	}
}

import { css, html, LitElement } from "lit";
import { customElement, state } from "lit/decorators.js";
import { styleMap } from "lit/directives/style-map.js";
import { getDraw, getTransport, Sequence } from "tone";

import { Bindable } from "../bind";
import { focusOutline, lightOrange, orange } from "../styles";

/**
 * Invoked for each filled cell at the time it should be played
 */
type StepSequencerCallback = (time: number, row: number) => void;

@customElement("tone-step-sequencer")
export class ToneStepSequencer
	extends LitElement
	implements Bindable<StepSequencerCallback>
{
	private readonly _columns = 16;

	private readonly _rows = 4;

	@state()
	private _highlighted = -1;

	private _sequencer: Sequence<number>;

	/**
	 * If each cell is filled, by column then row
	 */
	private _matrix = this._indexArray(this._columns).map(() =>
		this._indexArray(this._rows).map(() => false)
	);

	private _started = false;

	static override styles = [
		focusOutline,
		css`
			:host {
				display: block;
				width: 100%;
			}
			#container {
				display: flex;
			}
			.column {
				flex: 1;
				display: flex;
				flex-direction: column;
			}
			.column[highlighted] {
				background-color: color-mix(
					in srgb,
					${orange} 50%,
					transparent
				);
			}
			.cell {
				margin: 2px;
				flex: 1;
				background-color: #aaa;
				border: none;
			}
			.cell[filled] {
				background-color: black;
			}
			.column[highlighted] .cell:not([filled]) {
				background-color: ${lightOrange};
			}
			.column[highlighted] .cell[filled] {
				transform: scale(1.2);
			}
		`,
	];

	bind(callback: StepSequencerCallback) {
		this.addEventListener(
			"trigger",
			({ detail }: CustomEvent<{ time: number; row: number }>) =>
				callback(detail.time, detail.row)
		);
	}

	override connectedCallback() {
		super.connectedCallback();
		getTransport().on("start", this._onStart);
		getTransport().on("stop", this._onStop);
		this._sequencer = new Sequence(
			this._tick.bind(this),
			this._indexArray(this._columns),
			"8n"
		).start(0);
	}

	override disconnectedCallback() {
		super.disconnectedCallback();
		getTransport().off("start", this._onStart);
		getTransport().off("stop", this._onStop);
		this._sequencer.dispose();
	}

	private _onStart = () => {
		this._started = true;
	};

	private _onStop = () => {
		this._highlighted = -1;
		this._started = false;
	};

	private _indexArray(count: number): number[] {
		return Array.from({ length: count }, (_, i) => i);
	}

	private _tick(time: number, index: number) {
		getDraw().schedule(() => {
			if (this._started) {
				this._highlighted = index;
			}
		}, time);
		this._matrix[index].forEach((value, row) => {
			if (value) {
				this.dispatchEvent(
					new CustomEvent("trigger", {
						detail: {
							time,
							row: this._rows - row - 1,
						},
						composed: true,
					})
				);
			}
		});
	}

	private _updateCell(column: number, row: number) {
		this._matrix[column][row] = !this._matrix[column][row];
		this.requestUpdate();
	}

	private _mouseover(e: MouseEvent, column: number, row: number) {
		if (e.buttons) {
			this._updateCell(column, row);
		}
	}

	protected override render() {
		const containerStyle = {
			height: "auto",
			aspectRatio: `${this._columns} / ${this._rows}`,
		};
		return html`
			<div id="container" style=${styleMap(containerStyle)}>
				${this._matrix.map(
					(column, x) => html`
						<div
							class="column"
							?highlighted=${x === this._highlighted}
						>
							${column.map(
								(cell, y) => html`
									<button
										@mouseover=${(e: MouseEvent) =>
											this._mouseover(e, x, y)}
										@mousedown=${(e: MouseEvent) =>
											this._mouseover(e, x, y)}
										class="cell focus-outline"
										?filled=${cell}
									></button>
								`
							)}
						</div>
					`
				)}
			</div>
		`;
	}
}

declare global {
	interface HTMLElementTagNameMap {
		"tone-step-sequencer": ToneStepSequencer;
	}
}

/**
 * The globals which tone-ui.js adds to the example pages
 */
import type * as ToneModule from "tone";

type Node = ToneModule.ToneAudioNode;

interface NodeOptions {
	name?: string;
}

interface Folder extends HTMLElement {
	add(tone: Node, options?: NodeOptions): this;
}

interface Drawer extends Folder {
	folder(name: string): Folder;
}

interface PianoInstrument {
	triggerAttack(note: string, time?: number, velocity?: number): unknown;
	triggerRelease(noteOrTime?: string | number): unknown;
}

interface SliderPadPosition {
	x: number;
	y: number;
}

/**
 * What each kind of element can be bound to
 */
type BindTarget =
	// tone-play-toggle and tone-momentary-button
	| { start(): unknown; stop(): unknown }
	// tone-momentary-button
	| { triggerAttack(): unknown; triggerRelease(): unknown }
	// tone-slider
	| ToneModule.Param<any>
	| ToneModule.Signal<any>
	| ((value: number) => void)
	// tone-button
	| (() => void)
	// tone-mic-button
	| ToneModule.UserMedia
	// tone-step-sequencer
	| ((time: number, row: number) => void)
	// tone-slider-pad
	| {
			down?(position: SliderPadPosition): void;
			move?(position: SliderPadPosition): void;
			up?(position: SliderPadPosition): void;
	  }
	// tone-piano
	| PianoInstrument;

declare global {
	const Tone: typeof ToneModule;
	function bind(selector: string | Element, target: BindTarget): Element;
	function ui(tone: Node, options?: NodeOptions): HTMLElement;
	function drawer(): Drawer;
	function piano(instrument: PianoInstrument): HTMLElement;
	function meter(tone: ToneModule.Meter<number>): HTMLElement;
	function fft(tone: ToneModule.FFT): HTMLElement;
	function waveform(tone: ToneModule.Waveform): HTMLElement;
}

import { pageStyles } from "./styles";

/**
 * Add the boilerplate that every example page needs to the document head,
 * so the pages only have to include the script.
 */
export function addHeadElements() {
	const script = document.currentScript as HTMLScriptElement | null;
	const base = script?.src ?? document.baseURI;
	addOnce('meta[name="viewport"]', "meta", {
		name: "viewport",
		content: "width=device-width, initial-scale=1, maximum-scale=1",
	});
	addOnce('link[rel="icon"]', "link", {
		rel: "icon",
		type: "image/png",
		href: new URL("favicon.png", base).href,
	});
	if (!document.adoptedStyleSheets.includes(pageStyles.styleSheet)) {
		document.adoptedStyleSheets = [
			...document.adoptedStyleSheets,
			pageStyles.styleSheet,
		];
	}
	addOnce('link[href*="Hanken+Grotesk"]', "link", {
		rel: "stylesheet",
		href: "https://fonts.googleapis.com/css2?family=Hanken+Grotesk:wght@400;500;600;700&family=Geist+Mono:wght@400;500&display=swap",
	});
	addOnce('link[href*="Material+Icons"]', "link", {
		rel: "stylesheet",
		href: "https://fonts.googleapis.com/css?family=Material+Icons&display=block",
	});
}

function addOnce(
	selector: string,
	tagName: string,
	attributes: Record<string, string>
) {
	if (!document.head.querySelector(selector)) {
		const element = document.createElement(tagName);
		for (const [name, value] of Object.entries(attributes)) {
			element.setAttribute(name, value);
		}
		document.head.appendChild(element);
	}
}

