@customElement("tone-mute")
export class ToneMuteButton extends LitElement {
	@state()
	private _muted = true;

	@state()
	private _suspended = getContext().state === "suspended";

	static override styles = [
		icons,
		css`
			:host {
				display: flex;
			}

			button {
				appearance: none;
