		if (this._suspended) {
			await start();
		} else {
			this._muted = !this._muted;
		}
	}

	protected override render() {
		const silent = this._muted || this._suspended;
		return html`
			<button aria-label="mute" @click=${this._clicked}>
				<md-icon class=${classMap({ muted: silent })}>
					${silent ? "⊘" : "♪"}
				</md-icon>
			</button>
		`;
	}
}

