import "./octave";

import AudioKeys from "audiokeys";
import { css, html, LitElement } from "lit";
import { customElement, property, queryAll } from "lit/decorators.js";

import { ToneKeyboardNote } from "./note";
import { ToneKeyboardOctave } from "./octave";

@customElement("tone-keyboard")
export class ToneKeyboard extends LitElement {
	@property({ type: Number })
	rootOctave = 4;

	@property({ type: Number })
	octaves = 4;

	@queryAll("tone-keyboard-octave")
	private _octaves: NodeListOf<ToneKeyboardOctave>;

	private _computerKeyboard: AudioKeys;

	static override styles = css`
		#container {
			display: flex;
			background-color: white;
			height: 80px;
		}

		tone-keyboard-octave {
			flex-grow: 1;
		}
	`;

	constructor() {
		super();
		this._computerKeyboard = new AudioKeys({ polyphony: Infinity });
		this._computerKeyboard.down((e) => this._noteon(e.note));
		this._computerKeyboard.up((e) => this._noteoff(e.note));
	}

	private _getNoteByTouchId(id: number): ToneKeyboardNote | undefined {
		for (const octave of Array.from(this._octaves)) {
			const note = octave.getNoteByTouchId(id);
			if (note) {
				return note;
			}
		}
	}

	private _getOctave(midi: number): ToneKeyboardOctave | undefined {
		const octaveNumber = Math.floor(midi / 12);
		return Array.from(this._octaves).find((o) => o.octave === octaveNumber);
	}

	private _touchmove(event: TouchEvent) {
		Array.from(event.changedTouches).forEach((e) => {
			const activeNote = this._getNoteByTouchId(e.identifier);
			const element = this.shadowRoot.elementFromPoint(
				e.clientX,
				e.clientY
			);
			if (element && element.shadowRoot) {
				const note = element.shadowRoot.elementFromPoint(
					e.clientX,
					e.clientY
				) as ToneKeyboardNote | undefined;
				if (note && note.note && activeNote.note !== note.note) {
					activeNote.active = false;
					activeNote.touchId = -1;
					note.active = true;
					note.touchId = e.identifier;
				}
			}
		});
	}

	private _touchend(event: TouchEvent) {
		Array.from(event.changedTouches).forEach((e) => {
			const activeNote = this._getNoteByTouchId(e.identifier);
			if (activeNote && activeNote.active) {
				activeNote.active = false;
				activeNote.touchId = -1;
			}
		});
	}

	private _noteon(midi: number) {
		this._getOctave(midi)?.noteon(midi);
	}

	private _noteoff(midi: number) {
		this._getOctave(midi)?.noteoff(midi);
	}

	protected override render() {
		const octaves = Array.from(
			{ length: this.octaves },
			(_, i) => i + this.rootOctave
		);
		return html`
			<div
				id="container"
				@touchmove=${this._touchmove}
				@touchend=${this._touchend}
			>
				${octaves.map(
					(o) => html`
						<tone-keyboard-octave
							octave=${o}
						></tone-keyboard-octave>
					`
				)}
			</div>
		`;
	}
}

import { css, html, LitElement, nothing } from "lit";
import { customElement, state } from "lit/decorators.js";
import { classMap } from "lit/directives/class-map.js";
import WebMidi, { InputEventNoteoff, InputEventNoteon } from "webmidi";

@customElement("tone-midi-in")
export class ToneMidiIn extends LitElement {
	@state()
	private _connected = false;

	@state()
	private _flashing = false;

	private _flashTimeout: ReturnType<typeof setTimeout>;

	static override styles = css`
		:host {
			display: block;
		}

		#container {
			display: block;
			margin-bottom: 10px;
			position: relative;
		}
		label {
			margin-right: 5px;
			font-size: 0.7em;
		}

		select,
		label {
			display: inline-block;
		}

		#light {
			width: 10px;
			height: 10px;
			background-color: white;
			display: inline-block;
		}
		#light.connected {
			background-color: #aaa;
		}

		#light.connected.flash {
			background-color: black !important;
		}
	`;

	constructor() {
		super();
		WebMidi.enable((err) => {
			if (!err) {
				WebMidi.addListener("connected", (e) => {
					if (e.port.type === "input") {
						this.requestUpdate();
					}
				});
				WebMidi.addListener("disconnected", () => {
					this.requestUpdate();
				});
			}
		});
	}

	private _flash() {
		clearTimeout(this._flashTimeout);
		this._flashing = true;
		this._flashTimeout = setTimeout(() => (this._flashing = false), 100);
	}

	private _dispatchNote(
		eventName: "noteon" | "noteoff",
		e: InputEventNoteon | InputEventNoteoff
	) {
		this._flash();
		this.dispatchEvent(
			new CustomEvent(eventName, {
				detail: {
					name: `${e.note.name}${e.note.octave}`,
					midi: e.note.number,
					velocity: e.velocity,
				},
				composed: true,
				bubbles: true,
			})
		);
	}

	private _connectMidi(event: Event) {
		const id = (event.target as HTMLSelectElement).value;
		this._connected = id !== "none";
		if (!this._connected) {
			return;
		}
		const input = WebMidi.getInputById(id);
		if (input) {
			input.addListener("noteon", "all", (e) =>
				this._dispatchNote("noteon", e)
			);
			input.addListener("noteoff", "all", (e) =>
				this._dispatchNote("noteoff", e)
			);
			input.addListener("controlchange", "all", () => this._flash());
		}
	}

	protected override render() {
		if (!WebMidi.supported) {
			return nothing;
		}
		const lightClasses = {
			connected: this._connected,
			flash: this._flashing,
		};
		return html`
			<div id="container">
				<div id="light" class=${classMap(lightClasses)}></div>
				<label>MIDI IN:</label>
				<select @change=${this._connectMidi}>
					<option value="none">none</option>
					${WebMidi.inputs.map(
						(input) => html`
							<option value=${input.id}>${input.name}</option>
						`
					)}
				</select>
			</div>
		`;
	}
}

import { css, html, LitElement, nothing, PropertyValues } from "lit";
import { customElement, property, query } from "lit/decorators.js";
import { styleMap } from "lit/directives/style-map.js";
import { isDefined, Midi } from "tone";

@customElement("tone-keyboard-note")
export class ToneKeyboardNote extends LitElement {
	@property({ type: Number })
	note: number;

	@property({ type: String })
	color = "#eee";

	@property({ type: Boolean })
	active = false;

	@property({ type: Number })
	touchId = -1;

	@query("button")
	private _button: HTMLButtonElement;

	static override styles = css`
		:host {
			display: block;
		}

		#container {
			width: 100%;
			height: 100%;
			display: block;
		}
		#container:not([show]) {
			opacity: 0;
			margin: 2px;
			pointer-events: none;
		}

		button {
			appearance: none;
			width: 100%;
			height: 100%;
			border: 2px solid white;
			box-sizing: border-box;
			padding: 0;
			outline: none;
			transition: background-color 0.2s;
			color: transparent;
			font-size: 0px;
			border-radius: 2px;
		}
		/* overrides the key color of the inline style */
		button[active] {
			background-color: #666 !important;
			transition-duration: 0s;
		}
		button:focus {
			border-color: #666;
		}
	`;

	protected override updated(changed: PropertyValues<this>) {
		if (changed.has("active") && isDefined(changed.get("active"))) {
			const eventName = this.active ? "noteon" : "noteoff";
			if (!this.active) {
				this.touchId = -1;
			}
			this.dispatchEvent(
				new CustomEvent(eventName, {
					detail: {
						name: this._fromMidi(this.note),
						midi: this.note,
						velocity: this.active ? 1 : 0,
					},
					composed: true,
					bubbles: true,
				})
			);
		}
	}

	private _fromMidi(midi: number): string {
		return Midi(midi).toNote();
	}

	private _mouseover(e: MouseEvent) {
		if (e.buttons) {
			this.active = true;
			this._button.focus();
		}
	}

	private _keydown(e: KeyboardEvent) {
		if (!e.repeat && (e.key === " " || e.key === "Enter")) {
			this.active = true;
		}
	}

	private _keyup(e: KeyboardEvent) {
		if (e.key === " " || e.key === "Enter") {
			this.active = false;
		}
	}

	private _touchstart(e: TouchEvent) {
		e.preventDefault();
		this.touchId = e.touches[0].identifier;
		this.active = true;
	}

	private _press() {
		this.active = true;
	}

	private _release() {
		this.active = false;
	}

	protected override render() {
		const show = this.note !== 0;
		const buttonStyle = { backgroundColor: this.color };
		return html`
			<div id="container" ?show=${show}>
				${show
					? html`<button
							?active=${this.active}
							@mouseover=${this._mouseover}
							@mouseleave=${this._release}
							@mousedown=${this._press}
							@touchstart=${this._touchstart}
							@touchend=${this._release}
							@mouseup=${this._release}
							@keydown=${this._keydown}
							@keyup=${this._keyup}
							style=${styleMap(buttonStyle)}
						>
							${this._fromMidi(this.note).replace("#", "♯")}
						</button>`
					: nothing}
			</div>
		`;
	}
}

